
fn seeded(n:u64)->sha3::Shake256Reader{let mut h=Shake256::default();h.update(b"fixed-input-rng-anf-validation-v1");h.update(&n.to_le_bytes());h.finalize_xof()}
fn main(){let args:Vec<_>=std::env::args().collect();let ops=load_ops(&args[1]).unwrap();let(nq,nb,_,regs)=analyze_ops(ops.iter());assert!(args.len()>=5,"certified-region summary paths required");let mut ranges=Vec::new();for path in &args[4..]{let summary:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();assert_eq!(summary["full_operation_count"].as_u64().unwrap(),ops.len()as u64);for region in summary["selected_disjoint_certified_regions"].as_array().unwrap(){let start=region[0].as_u64().unwrap()as usize;let end=region[1].as_u64().unwrap()as usize;assert!(start<=end&&end<ops.len()&&end-start<10000);ranges.push((start,end));}}ranges.sort_unstable_by_key(|(a,b)|(*a,std::cmp::Reverse(*b)));ranges.dedup();let mut selected=Vec::new();for(a,b)in ranges{if selected.last().map_or(true,|(_,end)|a>*end){selected.push((a,b));}}let mut skip=vec![false;ops.len()];let mut methods=[0usize;2];for(start,end)in &selected{let span=&ops[*start..=*end];if coeff_projection::prove(span){methods[0]+=1;}else if symbol_projection::prove(span){methods[1]+=1;}else{panic!("selected reset projection did not re-prove: {start}..{end}");}for i in *start..=*end{if matches!(ops[i].kind,OperationType::X|OperationType::CX|OperationType::CCX|OperationType::Swap){skip[i]=true;}}}let removed=skip.iter().filter(|v|**v).count();eprintln!("CERTIFIED_RESET_REWRITE regions={} removed_value_ops={} methods={methods:?}",selected.len(),removed);let rows:Vec<Vec<U256>>=std::fs::read_to_string(&args[2]).unwrap().lines().filter(|l|!l.trim().is_empty()).map(|l|l.split_whitespace().skip(1).map(|v|U256::from_str_radix(v.trim_start_matches("0x"),16).unwrap()).collect()).collect();assert!(!rows.is_empty()&&rows.iter().all(|r|r.len()==6));let reduced:Vec<_>=ops.iter().enumerate().filter(|(i,_)|!skip[*i]).map(|(_,o)|o.clone()).collect();let mr=|p:&[Op]|p.iter().filter(|o|matches!(o.kind,OperationType::R|OperationType::Hmr)).count();assert_eq!(mr(&ops),mr(&reduced));let timer=std::time::Instant::now();let(mut batches,mut shots,mut dirtyshots,mut phase_differences)=(0,0,0,0);for dirty in [false,true]{let selected_rows=if dirty{&rows[..rows.len().min(64)]}else{&rows[..]};for data in selected_rows.chunks(64){for seed in 0..if dirty{4}else{2}{let mut random_a=seeded(seed);let mut random_b=seeded(seed);let mut original=Simulator::new(nq as usize,nb as usize,&mut random_a);let mut rewritten=Simulator::new(nq as usize,nb as usize,&mut random_b);if dirty{let mut junk=seeded(1000+seed);for q in &mut original.qubits{let mut raw=[0;8];XofReader::read(&mut junk,&mut raw);*q=u64::from_le_bytes(raw);}for b in &mut original.bits{let mut raw=[0;8];XofReader::read(&mut junk,&mut raw);*b=u64::from_le_bytes(raw);}}for(lane,row)in data.iter().enumerate(){for(reg,value)in regs[..4].iter().zip(&row[..4]){original.set_register(reg,*value,lane);}}rewritten.qubits.copy_from_slice(&original.qubits);rewritten.bits.copy_from_slice(&original.bits);original.apply_iter(ops.iter());rewritten.apply_iter(reduced.iter());assert_eq!(original.qubits,rewritten.qubits,"all-qubit rewrite mismatch fixture{} batch{batches} seed{seed} dirty{dirty}",args[2]);assert_eq!(original.bits,rewritten.bits,"all-classical rewrite mismatch fixture{} batch{batches} seed{seed} dirty{dirty}",args[2]);phase_differences+=usize::from(original.phase!=rewritten.phase);batches+=1;shots+=data.len();if dirty{dirtyshots+=data.len();}}}}let report=serde_json::json!({"source_stream":args[1],"fixture":args[2],"certified_regions":selected.len(),"reproved_methods":methods,"removed_quantum_value_operations":removed,"original_ops":ops.len(),"value_program_ops":reduced.len(),"mr_events_preserved":mr(&ops),"full_state_q_and_b_equal":true,"protected_batches":batches,"shots_including_dirty_auxiliary_controls":shots,"dirty_auxiliary_control_shots":dirtyshots,"independent_mr_seeds_real_inputs":2,"independent_mr_seeds_dirty_auxiliary_controls":4,"phase_not_part_of_value_certificate":true,"phase_difference_batches_diagnostic_only":phase_differences,"seconds":timer.elapsed().as_secs_f64(),"status":"EXACT_VALUE_PROGRAM_DIFFERENTIAL_NOT_A_BENCHMARK_OR_GLOBAL_RNG_PROOF"});println!("{report}");}
